/* ==================== HELPERS ==================== */
function h($s): string {
    return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
}

function base_real(): string {
    $b = realpath(BASE_DIR);
    if (!$b) {
        die("Invalid BASE_DIR");
    }
    return rtrim($b, '/');
}

function safe_join($rel): string {
    $base = base_real();
    $rel = ltrim((string)$rel, '/');
    $full = realpath($base . '/' . $rel);
    if (!$full) {
        return $base . '/' . $rel;
    }
    if (strpos($full, $base) !== 0) {
        die("Access denied");
    }
    return $full;
}

function copyRecursive($src, $dst): void {
    if (is_dir($src)) {
        if (!is_dir($dst)) {
            mkdir($dst, 0777, true);
        }
        foreach (scandir($src) as $file) {
            if ($file === '.' || $file === '..') {
                continue;
            }
            copyRecursive("$src/$file", "$dst/$file");
        }
    } else {
        copy($src, $dst);
    }
}

