/* ================ PATH ================ */
$path = $_GET['p'] ?? '';
$cwd = safe_join($path);

/* ================ CREATE ================ */
if (isset($_POST['create_folder'])) {
    $name = trim($_POST['folder_name'] ?? '');
    if ($name !== '') {
        mkdir($cwd . '/' . $name);
    }
}
if (isset($_POST['create_file'])) {
    $name = trim($_POST['file_name'] ?? '');
    if ($name !== '') {
        file_put_contents($cwd . '/' . $name, '');
    }
}

/* ================ UPLOAD ================ */
if (isset($_POST['upload_files'])) {
    foreach ($_FILES['files']['tmp_name'] as $k => $tmp) {
        $name = basename($_FILES['files']['name'][$k]);
        move_uploaded_file($tmp, $cwd . '/' . $name);
    }
}

/* ================ RENAME ================ */
if (isset($_POST['rename_file'])) {
    $oldName = trim($_POST['old_name'] ?? '');
    $newName = trim($_POST['new_name'] ?? '');
    if ($oldName !== '' && $newName !== '') {
        $oldPath = $cwd . '/' . $oldName;
        $newPath = $cwd . '/' . basename($newName);
        if (!file_exists($oldPath)) {
            $_SESSION['move_error'] = 'Source not found.';
        } elseif (file_exists($newPath)) {
            $_SESSION['move_error'] = 'Destination already exists.';
        } elseif (!rename($oldPath, $newPath)) {
            $_SESSION['move_error'] = 'Rename failed.';
        } else {
            $_SESSION['move_success'] = "Renamed '$oldName' to '$newName'.";
        }
    }
    header("Location: ?p=" . urlencode($path));
    exit;
}

/* ================ DELETE ================ */
if (isset($_POST['delete_file'])) {
    $deleteName = trim($_POST['delete_name'] ?? '');
    if ($deleteName !== '') {
        $file = $cwd . '/' . $deleteName;
        if (is_dir($file)) {
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($file, FilesystemIterator::SKIP_DOTS),
                RecursiveIteratorIterator::CHILD_FIRST
            );
            foreach ($iterator as $f) {
                $f->isDir() ? rmdir($f->getRealPath()) : unlink($f->getRealPath());
            }
            rmdir($file);
        } else {
            unlink($file);
        }
    }
    header("Location: ?p=" . urlencode($path));
    exit;
}

/* ================ EXTRACT ZIP (with relative destination) ================ */
if (isset($_POST['extract_zip'])) {
    $zipName = basename($_POST['zip_name'] ?? '');
    $destPathInput = trim($_POST['extract_dest_path'] ?? '');
    
    if ($destPathInput === '') {
        // Empty: extract to folder named after ZIP in current directory
        $destFull = $cwd . '/' . pathinfo($zipName, PATHINFO_FILENAME);
    } elseif (str_starts_with($destPathInput, '/')) {
        // Starts with '/': treat as absolute path within BASE_DIR
        $destFull = safe_join(ltrim($destPathInput, '/'));
    } else {
        // Relative path: append to current directory
        $destFull = safe_join(($path ? $path . '/' : '') . $destPathInput);
    }
    
    $zipPath = $cwd . '/' . $zipName;
    
    if (!file_exists($zipPath) || !is_file($zipPath)) {
        $_SESSION['move_error'] = 'ZIP file not found.';
    } else {
        $zip = new ZipArchive();
        if ($zip->open($zipPath) === true) {
            if (!is_dir($destFull)) {
                if (!mkdir($destFull, 0777, true)) {
                    $_SESSION['move_error'] = 'Failed to create destination folder.';
                    header("Location: ?p=" . urlencode($path));
                    exit;
                }
            }
            if (!$zip->extractTo($destFull)) {
                $_SESSION['move_error'] = 'Extraction failed.';
            } else {
                $_SESSION['move_success'] = "ZIP extracted successfully to: " . $destFull;
            }
            $zip->close();
        } else {
            $_SESSION['move_error'] = 'Failed to open ZIP file.';
        }
    }
    header("Location: ?p=" . urlencode($path));
    exit;
}

/* ================ ZIP SELECTED ================ */
if (isset($_POST['zip_selected']) && !empty($_POST['selected'])) {
    $zipName = "archive_" . date("Ymd_His") . ".zip";
    $zipPath = sys_get_temp_dir() . "/" . $zipName;
    $zip = new ZipArchive();
    $zip->open($zipPath, ZipArchive::CREATE);
    foreach ($_POST['selected'] as $item) {
        $full = $cwd . '/' . $item;
        if (is_dir($full)) {
            $files = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($full, FilesystemIterator::SKIP_DOTS),
                RecursiveIteratorIterator::LEAVES_ONLY
            );
            foreach ($files as $file) {
                if (!$file->isDir()) {
                    $zip->addFile(
                        $file->getRealPath(),
                        substr($file->getRealPath(), strlen($cwd) + 1)
                    );
                }
            }
        } else {
            $zip->addFile($full, basename($full));
        }
    }
    $zip->close();
    header('Content-Type: application/zip');
    header('Content-Disposition: attachment; filename="' . $zipName . '"');
    readfile($zipPath);
    unlink($zipPath);
    exit;
}

/* ================ MOVE SELECTED ================ */
if (isset($_POST['move_selected']) && isset($_POST['selected']) && isset($_POST['dest_path'])) {
    $destPath = trim($_POST['dest_path']);
    if ($destPath !== '') {
        $destFull = safe_join($destPath);
        if (!is_dir($destFull)) {
            $_SESSION['move_error'] = "Destination path invalid.";
        } else {
            $errors = [];
            $success = [];
            foreach ($_POST['selected'] as $item) {
                $source = $cwd . '/' . $item;
                $destItem = $destFull . '/' . basename($item);
                if (file_exists($destItem)) {
                    $errors[] = "'$item' exists.";
                    continue;
                }
                if (rename($source, $destItem)) {
                    $success[] = $item;
                } else {
                    $errors[] = "Failed '$item'";
                }
            }
            if ($success) {
                $_SESSION['move_success'] = "Moved: " . implode(', ', $success);
            }
            if ($errors) {
                $_SESSION['move_error'] = implode(' ', $errors);
            }
        }
    }
    header("Location: ?p=" . urlencode($path));
    exit;
}

/* ================ COPY SELECTED ================ */
if (isset($_POST['copy_selected']) && isset($_POST['selected']) && isset($_POST['copy_dest_path'])) {
    $destPath = trim($_POST['copy_dest_path']);
    if ($destPath !== '') {
        $destFull = safe_join($destPath);
        if (!is_dir($destFull)) {
            $_SESSION['move_error'] = "Copy destination invalid.";
        } else {
            $errors = [];
            $success = [];
            foreach ($_POST['selected'] as $item) {
                $source = $cwd . '/' . $item;
                $destItem = $destFull . '/' . basename($item);
                if (file_exists($destItem)) {
                    $errors[] = "'$item' exists.";
                    continue;
                }
                copyRecursive($source, $destItem);
                $success[] = $item;
            }
            if ($success) {
                $_SESSION['move_success'] = "Copied: " . implode(', ', $success);
            }
            if ($errors) {
                $_SESSION['move_error'] = implode(' ', $errors);
            }
        }
    }
    header("Location: ?p=" . urlencode($path));
    exit;
}

