    </form>

    <script>
        function openModal(id) {
            document.getElementById(id).classList.remove('hidden');
            document.getElementById(id).classList.add('flex');
        }
        function closeModal(id) {
            document.getElementById(id).classList.add('hidden');
            document.getElementById(id).classList.remove('flex');
        }
        function renameItem(name) {
            let newName = prompt("Rename:", name);
            if (newName && newName !== name) {
                document.getElementById('rename_old').value = name;
                document.getElementById('rename_new').value = newName;
                document.getElementById('renameForm').submit();
            }
        }
        function deleteItem(name) {
            if (confirm('Delete "' + name + '"?')) {
                document.getElementById('delete_name_input').value = name;
                document.getElementById('deleteForm').submit();
            }
        }
        function extractZip(name) {
            let defaultDest = "<?= addslashes($path) ?>";
            let destPath = prompt("Extract \"" + name + "\" to folder:", defaultDest);
            if (destPath !== null) {
                document.getElementById('extract_zip_name').value = name;
                document.getElementById('extract_dest_path').value = destPath;
                document.getElementById('extractForm').submit();
            }
        }
        const selectAllCheckbox = document.getElementById('selectAllCheckbox');
        const itemCheckboxes = document.querySelectorAll('.item-checkbox');
        if (selectAllCheckbox) {
            selectAllCheckbox.addEventListener('change', function(e) {
                itemCheckboxes.forEach(cb => cb.checked = e.target.checked);
            });
        }
        document.getElementById('zipSelectedBtn').addEventListener('click', function() {
            let anyChecked = Array.from(itemCheckboxes).some(cb => cb.checked);
            if (!anyChecked) {
                alert('Select items first');
                return;
            }
            document.getElementById('zipForm').submit();
        });
        function injectSelected(formId) {
            const form = document.getElementById(formId);
            form.querySelectorAll('input[name="selected[]"]').forEach(e => e.remove());
            let checked = document.querySelectorAll('.item-checkbox:checked');
            if (checked.length === 0) {
                alert('Please select at least one item.');
                return false;
            }
            checked.forEach(cb => {
                let input = document.createElement('input');
                input.type = 'hidden';
                input.name = 'selected[]';
                input.value = cb.value;
                form.appendChild(input);
            });
            return true;
        }
        document.getElementById('moveForm').addEventListener('submit', function(e) {
            if (!injectSelected('moveForm')) e.preventDefault();
        });
        document.getElementById('copyForm').addEventListener('submit', function(e) {
            if (!injectSelected('copyForm')) e.preventDefault();
        });
    </script>
</body>
</html>